import{_ as t,o,c as a,a3 as s}from"./chunks/framework.Mjix4IZ4.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),d={name:"explanation/architecture.md"};function r(c,e,i,n,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Rust workspace, ports-and-adapters. <code>lasius-core</code> is pure domain (no I/O); <code>lasius-cli</code> is the composition root.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>The org stack is <strong>delivery → memory → process → interface</strong>. Lasius is a <strong>process-layer organism</strong> — git &amp; workspace expertise, repo-local, no hosted state. It manages the <em>clones</em> every other organism lives in: <code>lasius-vcs</code>/<code>lasius-forge</code> are shared ports consumed across the stack (tarsi, mimus, bupha, kuda, sturn); <code>lasius serve</code> exposes read-only ops on the org wire convention; the process layer (<code>peregrin</code>) and the interface (<code>pavo</code>) consume lasius output like any other organism&#39;s.</p><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>lasius-core</code></td><td>domain</td><td>Pure domain logic for lasius — config model, gh decoding, git status, workspace files</td></tr><tr><td><code>lasius-forge</code></td><td>port</td><td>Forge port — pull requests, merges, and check status, generic over the backend.</td></tr><tr><td><code>lasius-vcs</code></td><td>port</td><td>VCS port — history/worktree/tag/sync ops, generic over the backend (P-019).</td></tr><tr><td><code>lasius-forge-gh</code></td><td>adapter</td><td>GitHub impl of lasius-forge — shells out to the gh CLI.</td></tr><tr><td><code>lasius-vcs-git</code></td><td>adapter</td><td>Git impl of lasius-vcs — shells out to the git binary.</td></tr><tr><td><code>lasius</code></td><td>engine</td><td>lasius — the engine as a library. Everything that used to live in the binary lives here: <code>Cli</code>/<code>Cmd</code>, workspace resolution, verb dispatch.</td></tr><tr><td><code>lasius-driver</code></td><td>driver</td><td>tamias-driver-lasius — pavo driver exposing a lasius workspace&#39;s engine ops (no views)</td></tr><tr><td><code>lasius-xtask</code></td><td>tooling</td><td>lasius-xtask — workspace automation: check / test / coverage / pack / install / fmt.</td></tr></tbody></table><p>The <code>lasius</code> command itself ships as the tamias pack in <code>libraries/lasius/</code> (<code>tamias.yaml</code> declares <code>bins: [{name: lasius, shim: cli, driver: lasius}]</code>; <code>cargo xtask pack</code> stages the driver payload, gitignored).</p><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><p>Provider discovery (<code>provider = &quot;github&quot;</code> → <code>gh repo list --json</code>) → decode + filter (archived, private, exclude globs, unsafe names) → <code>git clone</code> into <code>repos_dir</code> → scan local clones for status/update/workspace-file generation.</p><p><code>status</code>/<code>update</code>/<code>code-workspace generate</code> iterate the local clones, not the provider&#39;s repo list — a manually added clone is managed too, and a repo deleted upstream still gets pulled until removed.</p><p>Per-repo failures never abort a batch: <code>clone</code>/<code>update</code>/<code>status</code> collect them and report at the end, with stderr classified (<code>access-denied:</code>, <code>not-found:</code>) so credential and permission problems are obvious. <code>check</code> adds <code>remote-reachable</code>, which probes each clone&#39;s <code>origin</code> via <code>git ls-remote</code> with credential prompts disabled and a 20s timeout, so a hung network can&#39;t stall the run.</p><h2 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;Safety&quot;">​</a></h2><ul><li>Repo names from <code>gh</code> are validated before they become path segments.</li><li><code>rm</code> refuses dirty trees, unpushed commits, stashes, linked worktrees, nested <code>.git</code> dirs, and extra remotes unless <code>--force</code>.</li><li>Generated files (<code>*.code-workspace</code>) and <code>repos/</code> are gitignored — the workspace repo tracks config and docs only.</li></ul><p>See <a href="./boundaries.html">Boundaries</a> for owns / does-not-own.</p>',13)])])}const m=t(d,[["render",r]]);export{u as __pageData,m as default};
